package net.officefloor.hq.app;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.sheet.SheetArchive;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * A viewer sees every screen and changes nothing: every write to a sheet (POST or PUT) by a user the sheet makes
 * a viewer is refused with a 400 before any step runs, so nothing is written nor audited. The bulk actions are let
 * through: they refuse each selected item themselves (the claim status rules refuse a viewer), reporting 0 done.
 * An archived sheet refuses every write the same way, whoever makes it.
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class ViewerGuard extends OncePerRequestFilter {

    private static final Pattern SHEET_WRITE = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");

    /** The writes that report per-item counts, so a viewer's press goes through with every item refused. */
    private static final Set<String> BULK = Set.of("/claims/bulk-open", "/claims/bulk-settle");

    private final Roles roles;
    private final SheetArchive archive;

    public ViewerGuard(Roles roles, SheetArchive archive) {
        this.roles = roles;
        this.archive = archive;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String method = request.getMethod();
        String user = request.getParameter("user");
        if (("POST".equals(method) || "PUT".equals(method)) && user != null) {
            Matcher m = SHEET_WRITE.matcher(request.getRequestURI().substring(request.getContextPath().length()));
            if (m.matches() && !BULK.contains(m.group(2) == null ? "" : m.group(2))) {
                String sheet = URLDecoder.decode(m.group(1), StandardCharsets.UTF_8);
                if (Role.VIEWER.equals(roles.of(sheet, user))) {
                    response.sendError(HttpServletResponse.SC_BAD_REQUEST, "A viewer cannot change the sheet");
                    return;
                }
                if (archive.archived(sheet)) {
                    response.sendError(HttpServletResponse.SC_BAD_REQUEST, "An archived sheet cannot change");
                    return;
                }
            }
        }
        chain.doFilter(request, response);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {
    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    private static final Pattern NUMBER = Pattern.compile("\\d{1,9}|\\S{1,200}-\\d{1,9}");

    public void validate(@PathVariable("sheet") String sheet, @RequestBody ClaimRequest request, SheetClock clock,
            Out<ClaimInput> body) throws InvalidClaimException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        String date = request == null || request.date() == null ? "" : request.date().trim();
        String note = request == null || request.note() == null ? "" : request.note().trim();
        String corrects = request == null || request.corrects() == null ? "" : request.corrects().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals");
        }
        // A negative amount is a correction: it must name, by the number it shows (on the sheet, or
        // within its period: <period>-<n>), the claim it corrects; no other claim may.
        BigDecimal value = new BigDecimal(amount);
        if (value.signum() < 0 && !NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("A negative amount must name the number of the claim it corrects");
        }
        if (value.signum() >= 0 && !corrects.isEmpty()) {
            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim");
        }
        LocalDate on;
        try {
            on = date.isEmpty() ? clock.today(sheet) : LocalDate.parse(date);
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("Not a valid date: " + date);
        }
        body.set(new ClaimInput(value, on, note, value.signum() < 0 ? numbered(corrects) : null));
    }

    /** The number as a claim shows it: a number on the sheet without leading zeros, a period number as given. */
    private static String numbered(String corrects) {
        return corrects.chars().allMatch(Character::isDigit) ? Integer.toString(Integer.parseInt(corrects)) : corrects;
    }
}
